Given the root of a Binary Search Tree (BST) and an integer key, find its inorder predecessor and inorder successor.The inorder predecessor is the node with the largest value smaller than key, and the inorder successor is the node with the smallest value greater than key. If either does not exist, return NULL for that position.Examples:Input:  Input: root = [50, 30, 70, 20, 40, 60, 80], key = 65 Output: [60, 70]Explanation: In given BST the inorder predecessor of 65 is 60 and inorder successor of 65 is 70. Input:  root = [8, 1, 9, N, 4, N, 10, 3], key = 8 Output: [4, 9]Explanation: In the given BST the inorder predecessor of 8 is 4 and inorder successor of 8 is 9. Try It YourselfTable of Content[Naive Approach] Maintaining predecessor and successors - O(n) Time and O(1) Space[Expected Approach-1] Using Two Traversals - O(h) Time and O(1) Space[Expected Approach-2] Using Single Traversal - O(h) Time and O(1) Space[Naive Approach] Maintaining predecessor and successors - O(n) Time and O(1) SpaceThe idea is to traverse the entire BST while maintaining the inorder predecessor and successor of the given key. For each node, if its value is smaller than the key, it can be a potential predecessor, so we update it if it is greater than the current predecessor. Similarly, if its value is greater than the key, it can be a potential successor, so we update it if it is smaller than the current successor.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;
    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// traversal to find 
// predecessor and successor
void preorder(Node* root, int key, Node*& pre, Node*& suc) {
    if (root == nullptr) return;

    if (root->data < key && (pre == nullptr || pre->data < root->data)) {
        pre = root;
    }

    if (root->data > key && (suc == nullptr || suc->data > root->data)) {
        suc = root;
    }

    preorder(root->left, key, pre, suc);
    preorder(root->right, key, pre, suc);
}

// return vector with predecessor at 
// index 0 and successor at index 1
vector<Node*> findPreSuc(Node* root, int key) {
    Node* pre = nullptr;
    Node* suc = nullptr;
    preorder(root, key, pre, suc);
    return {pre, suc};
}

int main() {
    // Create BST:
    //      50 
    //     /  \
    //   30     70
    //   / \    / \
    // 20  40  60  80

    int key = 65;
    Node* root = new Node(50);
    root->left = new Node(30);
    root->right = new Node(70);
    root->left->left = new Node(20);
    root->left->right = new Node(40);
    root->right->left = new Node(60);
    root->right->right = new Node(80);

    vector<Node*> result = findPreSuc(root, key);
    Node* pre = result[0];
    Node* suc = result[1];

    cout << (pre ? to_string(pre->data) : "NULL") << " ";
    cout << (suc ? to_string(suc->data) : "NULL") << endl;
}


